import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_config(config_path):
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = ET.fromstring(content)
        window_seconds = int(root.get('window_seconds'))
        clients = {}

        for client_elem in root.findall('client'):
            client_id = client_elem.get('id')
            max_active = int(client_elem.get('max_active'))
            max_new = int(client_elem.get('max_new'))
            tag = client_elem.get('tag')

            if not client_id or not tag:
                raise ValueError("Missing required client attributes")

            clients[client_id] = {
                'max_active': max_active,
                'max_new': max_new,
                'tag': tag
            }

        return window_seconds, clients
    except ET.ParseError as e:
        sys.exit(1)
    except ValueError as e:
        sys.exit(1)

def compute_signature(s):
    v = 0
    for c in s:
        u = ord(c)
        v = (v * 131 + u) % (2**64)
    return f"{v:016x}".lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: alloc_throttle.py CONFIG.xml")
        sys.exit(1)

    config_path = sys.argv[1]
    window_seconds, clients = parse_config(config_path)

    # Initialize state for each client
    active_count = defaultdict(int)
    allocation_history = defaultdict(list)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 3:
            continue

        client_id, timestamp_str, action = parts
        timestamp = int(timestamp_str)

        # Check if client exists in config
        if client_id not in clients:
            print(f"UNKNOWN {client_id}")
            continue

        # Remove timestamps older than window_seconds ago
        current_time = timestamp
        window_bound = current_time - window_seconds
        new_history = [t for t in allocation_history[client_id] if t >= window_bound]
        allocation_history[client_id] = new_history
        history_size = len(new_history)

        if action == "ALLOCATE":
            config = clients[client_id]
            active_count[client_id] += 1
            if active_count[client_id] > config['max_active']:
                active_count[client_id] -= 1
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            if history_size + 1 > config['max_new']:
                active_count[client_id] -= 1
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            allocation_history[client_id].append(timestamp)
            signature = compute_signature(f"{client_id}|{timestamp}|ALLOCATE|{config['tag']}")
            print(f"ALLOCATED {client_id} {timestamp} {signature}")

        elif action == "RELEASE":
            if active_count[client_id] > 0:
                active_count[client_id] -= 1
                signature = compute_signature(f"{client_id}|{timestamp}|RELEASE|{clients[client_id]['tag']}")
                print(f"RELEASED {client_id} {timestamp} {signature}")
            else:
                print(f"IGNORED {client_id} {timestamp}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import requests
import json
import os
from urllib.parse import urlparse
from requests.exceptions import RequestException

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def fetch_endpoints(config_path):
    if not os.path.isfile(config_path):
        print("{}")
        return

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        print("{}")
        return

    results = {}
    for endpoint in root.findall('endpoint'):
        name = endpoint.get('name')
        url = endpoint.get('url')

        if not name or not url or not is_valid_url(url):
            continue

        try:
            response = requests.get(url, timeout=10, verify=True)
            status = response.status_code
            body = response.text[:200]
        except RequestException:
            status = None
            body = ""

        results[name] = {
            "url": url,
            "status": status,
            "body": body
        }

    print(json.dumps(results))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python fetch_endpoints.py CONFIG_PATH")
    else:
        config_path = sys.argv[1]
        if not os.path.isabs(config_path):
            config_path = os.path.abspath(config_path)
        fetch_endpoints(config_path)

