            base_url = service.get('base_url')
            token_env = service.get('token_env')
            if name and base_url and token_env:
                services[name] = {'base_url': base_url, 'token_env': token_env}
        return services
    except ParseError:
        print("Error parsing services.xml")
        sys.exit(1)
    except FileNotFoundError:
