        print(f"Missing token for service: {service_name}")
        sys.exit(1)

def sanitize_path(path):
    if not path.startswith('/'):
        path = '/' + path
    return path.lstrip('/')

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <service_name> <path>")
        sys.exit(1)

