import sys
import json
import xml.etree.ElementTree as ET
import os
import defusedxml
from defusedxml import ElementTree as DefusedET

def parse_config(config_path):
    try:
        tree = DefusedET.parse(config_path)
        root = tree.getroot()
        calculations = {}
        for calc in root:
            name = calc.get('name')
            expr = calc.get('expr')
            if not name or not expr:
                raise ValueError("Missing 'name' or 'expr' attribute in calculation element")
            calculations[name] = expr
        return calculations
    except Exception as e:
        raise ValueError(f"Error parsing configuration file: {str(e)}")

def evaluate_expression(expr, variables):
    try:
        # Replace variable references with their values
        for var, value in variables.items():
            expr = expr.replace(f"{var}", str(value))
        # Use safe evaluation with ast.literal_eval for safe expression evaluation
        # Note: This only supports basic Python literals (int, float, str, tuple, list, dict, bool, None)
        # For more complex expressions, additional logic or a safe expression parser is needed
        # If the expression contains unsupported syntax, it will raise a ValueError
        import ast
        node = ast.parse(expr, mode='eval')
        result = eval(compile(node, '<string>', 'eval'), {'__builtins__': {}}, {})
        return float(result) if isinstance(result, (int, float)) else result
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {str(e)}")

def run_mode(config_path, input_json):
    # Parse configuration
    calculations = parse_config(config_path)

    # Read input JSON from stdin
    try:
        input_data = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON input: {str(e)}")

    # Evaluate each calculation
    results = {}
    for name, expr in calculations.items():
        try:
            result = evaluate_expression(expr, input_data)
            results[name] = result
        except Exception as e:
            raise ValueError(f"Error evaluating calculation '{name}': {str(e)}")

    # Output results to stdout
    print(json.dumps(results))

    # Create cache file with full state
    cache_path = "calcflow.cache"
    cache_data = {
        "variables": input_data,
        "calculations": results,
        "config": calculations
    }
    with open(cache_path, 'w') as f:
        json.dump(cache_data, f, indent=2)

    return results

def replay_mode(cache_path):
    # Read cache file
    if not os.path.exists(cache_path):
        raise FileNotFoundError(f"Cache file not found: {cache_path}")

    with open(cache_path, 'r') as f:
        cache_data = json.load(f)

    # Output results to stdout
    print(json.dumps(cache_data["calculations"]))

def main():
    if len(sys.argv) != 3:
        print("Usage: python calcflow.py run <CONFIG_PATH> or python calcflow.py replay <CACHE_PATH>", file=sys.stderr)
        sys.exit(1)

    mode = sys.argv[1]
    path = sys.argv[2]

    if mode == "run":
        run_mode(path, None)
    elif mode == "replay":
        replay_mode(path)
    else:
        print("Invalid mode. Use 'run' or 'replay'.", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import os

def parse_config(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
        max_total_bytes = int(root.find('maxTotalBytes').text)
        if max_total_bytes < 0:
            raise ValueError("maxTotalBytes must be non-negative")
        return max_total_bytes
    except ET.ParseError as e:
        raise ValueError(f"Error parsing XML: {e}")
    except Exception as e:
        raise ValueError(f"Error reading config file: {e}")

def sanitize_path(path):
    return os.path.normpath(os.path.abspath(path))

def read_workload(workload_path):
    try:
        with open(workload_path, 'r') as workload_file:
            return workload_file.readlines()
    except Exception as e:
        raise ValueError(f"Error reading workload file: {e}")

def process_instructions(instructions, max_total_bytes):
    user_allocations = {}
    total_allocated_bytes = 0

    for instruction in instructions:
        parts = instruction.strip().split()
        if len(parts) != 3 or parts[0] != 'ALLOCATE':
            continue

        user_id = parts[1]
        try:
            requested_bytes = int(parts[2])
            if requested_bytes < 0:
                raise ValueError("Requested bytes must be non-negative")
        except ValueError:
            continue

        if requested_bytes + total_allocated_bytes > max_total_bytes:
            print(f"THROTTLED {user_id} {requested_bytes}")
        else:
            if user_id not in user_allocations:
                user_allocations[user_id] = 0
            user_allocations[user_id] += requested_bytes
            total_allocated_bytes += requested_bytes
            print(f"ALLOCATED {user_id} {requested_bytes}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python allocator.py CONFIG_PATH")
        return

    config_path = sys.argv[1]
    try:
        max_total_bytes = parse_config(config_path)
    except ValueError as e:
        print(f"Error: {e}")
        return

    workload_path = input().strip()
    try:
        workload_path = sanitize_path(workload_path)
        if not os.path.isfile(workload_path):
            raise ValueError("Invalid workload file path")
        instructions = read_workload(workload_path)
    except ValueError as e:
        print(f"Error: {e}")
        return

    process_instructions(instructions, max_total_bytes)

if __name__ == "__main__":
    main()

