import sys
import json
import os
import subprocess
import hashlib

def load_cache():
    cache_file = 'command_cache.bin'
    if os.path.exists(cache_file):
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    with open('command_cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def run_command(command):
    result = subprocess.run(command, shell=False, capture_output=True, text=True)
    return result.returncode, result.stdout.strip()

def hash_command(command):
    return hashlib.sha256(command.encode()).hexdigest()

def main():
    if len(sys.argv) != 2:
        print("Usage: python batch_runner.py config.json")
        sys.exit(1)

    config_file = sys.argv[1]
    with open(config_file, 'r') as f:
        config = json.load(f)

    cache = load_cache()

    for item in config:
        name = item['name']
        command = item['command']
        command_hash = hash_command(command)

        if command_hash not in cache:
            exit_status, stdout = run_command(command)
            cache[command_hash] = (exit_status, stdout)
        else:
            exit_status, stdout = cache[command_hash]

        stdout_single_line = stdout.replace('\n', '\\n')
        print(f"{name}:{exit_status}:{stdout_single_line}")

    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import html
import secrets
import hmac
import time

def secure_compare(a, b):
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

def generate_secure_token(original_token):
    return hmac.new(original_token.encode(), str(time.time()).encode(), secrets.token_algorithm).hexdigest()

def validate_xml_structure(root):
    if root.tag != 'config':
        return False
    sessions = root.find('sessions')
    if sessions is None:
        return False
    for session in sessions.findall('session'):
        if not all(session.find(tag) is not None for tag in ['user', 'token', 'role']):
            return False
    return True

def main():
    if len(sys.argv) != 3:
        print("Usage: python login_portal.py <config_path> <access_token>")
        return

    config_path = sys.argv[1]
    access_token = sys.argv[2]

    if not config_path.startswith('/secure/path/'):
        print("INVALID_TOKEN")
        return

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        print("INVALID_TOKEN")
        return

    if not validate_xml_structure(root):
        print("INVALID_TOKEN")
        return

    sessions = root.find('sessions')
    for session in sessions.findall('session'):
        token = session.find('token').text
        if secure_compare(token, access_token):
            user = html.escape(session.find('user').text)
            role = html.escape(session.find('role').text)
            new_token = generate_secure_token(token)

            print(f"<html><head></head><body>")
            print(f"<h1>Welcome, {user}!</h1>")
            print(f"<p>Your new session token is: {new_token}</p>")
            print(f"<div id=\"dashboard\">")
            if role == 'admin':
                print(f"<h2>Admin dashboard</h2>")
                print(f"<ul><li>View metrics</li><li>Manage users</li><li>Review logs</li></ul>")
            else:
                print(f"<h2>User dashboard</h2>")
                print(f"<p>You have limited access.</p>")
            print(f"</div>")
            print(f"</body></html>")
            return

    print("INVALID_TOKEN")

if __name__ == "__main__":
    main()

